[
  {
    "statement": "There were no studies evaluating the cost-effectiveness of any method for reducing lethal vessel strikes on large whales.",
    "citations": [
      "2754",
      "2777",
      "2755"
    ]
  },
  {
    "statement": "A before-and-after study in the North Atlantic Ocean found that setting vessel speed limits during specific periods in key habitats resulted in fewer North Atlantic right whale deaths caused by collisions.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "A study on manatees in the Indian River estuarine system found fewer deaths after speed limits were set and enforced in all areas.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "There were no studies found that evaluated the effects of diverting shipping routes to prevent collisions.",
    "citations": [
      "2754",
      "2755"
    ]
  },
  {
    "statement": "There were no studies found that evaluated the effects of using on-board observers to prevent collisions.",
    "citations": [
      "2754",
      "2755"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects on marine and freshwater mammal populations of legally protecting areas where climate change impacts are predicted to be less severe.",
    "citations": [
      "2912"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of creating a marine protected area or setting levels of legal protection where natural climate refugia occur to further promote the persistence and recovery of species facing climate change.",
    "citations": [
      "2222"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of establishing a network of legally protected areas on marine and freshwater mammal populations.",
    "citations": [
      "2913"
    ]
  }
]

